+    fn the_invite_is_a_url_whose_fragment_carries_the_code() {
+        let identity = identity();
+        let window = PairingWindow {
+            until: Clock::at(0).mono,
+            code: "K7M2QX".into(),
+            scope: Scope::Read,
+            failures: 0,
