9	  info: '/api/v1/info',
10	  pair: '/api/v1/pair',
11	  me: '/api/v1/me',
12	  projects: '/api/v1/projects',
13	  sessions: '/api/v1/projects/{id}/sessions',
14	  waiting: '/api/v1/waiting',
15	  lastResponse: '/api/v1/sessions/{id}/last-response',
16	  screen: '/api/v1/sessions/{id}/screen',
17	  send: '/api/v1/sessions/{id}/send',
18	  events: '/api/v1/events',
19	};
20	
21	const STORE_KEY = 'switchboard-host';
22	const POLL_FAST = 3000;
23	const POLL_SLOW = 20000;
24	const RETRY_FIRST = 5000;
25	const RETRY_MAX = 60000;
26	
27	// --- pure parts
28	
29	function route(template, id) {
30	  return template.replace('{id}', encodeURIComponent(id));
31	}
32	
33	// `#code=..&key=..&id=..` -> the three values, or null if one is missing.
34	function parseFragment(hash) {
35	  const params = new URLSearchParams(hash.replace(/^#/, ''));
36	  const code = params.get('code');
37	  const key = params.get('key');
38	  const id = params.get('id');
39	  return code && key && id ? { code, key, id } : null;
40	}
41	
42	function deviceName(ua, touchPoints) {
43	  const browser = /Edg\//.test(ua)
44	    ? 'Edge'
45	    : /Chrome\/|CriOS/.test(ua)
46	      ? 'Chrome'
47	      : /Firefox\/|FxiOS/.test(ua)
48	        ? 'Firefox'
49	        : /Safari\//.test(ua)
50	          ? 'Safari'
51	          : null;
52	  let device = null;
53	  if (/iPhone/.test(ua)) device = 'iPhone';
54	  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
55	  else if (/Android/.test(ua)) device = 'Android';
56	  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
57	  else if (/Windows/.test(ua)) device = 'Windows';
58	  else if (/Linux/.test(ua)) device = 'Linux';
59	  return browser && device ? `${browser} on ${device}` : 'Browser';
60	}
61	
62	// What a 401 means, from what /info says now against what this page
63	// stored at pairing. The host cannot say "revoked": a removed device and
64	// an unknown token answer the same.
65	function infer401(stored, info) {
66	  if (!stored) return 'unpaired';
67	  if (!info) return 'unreachable';
68	  return info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256
69	    ? 'removed'
70	    : 'changed';
71	}
72	
73	// Whether a reply is newer than what is applied: a new epoch always is,
74	// the same epoch needs a revision no lower.
75	function isCurrent(applied, reply) {
76	  if (!applied || applied.epoch !== reply.epoch) return true;
77	  return reply.revision >= applied.revision;
78	}
79	
80	function randomHex(bytes) {
81	  const raw = new Uint8Array(bytes);
82	  crypto.getRandomValues(raw);
83	  return Array.from(raw, (b) => b.toString(16).padStart(2, '0')).join('');
84	}
85	
86	function ago(ms, now) {
87	  if (!ms) return '';
88	  const s = Math.max(0, Math.round((now - ms) / 1000));
89	  if (s < 60) return `${s}s ago`;
90	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
91	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
92	  return `${Math.floor(s / 86400)}d ago`;
93	}
94	
95	// Projects with a waiting session first, waiting sessions first inside.
96	function arrange(groups) {
97	  const waits = (g) => g.sessions.some((s) => s.waiting);
98	  groups.forEach((g) => g.sessions.sort((a, b) => Number(b.waiting) - Number(a.waiting)));
99	  return groups.slice().sort((a, b) => Number(waits(b)) - Number(waits(a)));
100	}
101	
102	// --- the page
103	
104	const page = {
105	  stored: null,
106	  me: null,
107	  groups: [],
108	  marker: null,
109	  applied: null,
110	  contentApplied: {},
111	  open: null,
112	  pending: {},
113	  pollTimer: null,
114	  pollMs: POLL_FAST,
115	  socket: null,
116	  retryMs: RETRY_FIRST,
117	  retryTimer: null,
118	  refreshing: false,
119	};
120	
121	function el(tag, text, className) {
122	  const node = document.createElement(tag);
123	  if (text !== undefined && text !== null) node.textContent = text;
124	  if (className) node.className = className;
125	  return node;
126	}
127	
128	function show(...nodes) {
129	  document.getElementById('app').replaceChildren(...nodes);
130	}
131	
132	function message(title, text, ...extra) {
133	  show(el('h2', title), el('p', text), ...extra);
134	}
135	
136	function loadStored() {
137	  try {
138	    return JSON.parse(localStorage.getItem(STORE_KEY));
139	  } catch {
140	    return null;
141	  }
142	}
143	
144	function saveStored(value) {
145	  localStorage.setItem(STORE_KEY, JSON.stringify(value));
146	}
147	
148	async function call(path, options) {
149	  const response = await fetch(path, { credentials: 'same-origin', ...options });
150	  let body = null;
151	  try {
152	    body = await response.json();
153	  } catch {
154	    body = null;
155	  }
156	  return { status: response.status, body };
157	}
158	
159	async function readInfo() {
160	  try {
161	    const r = await call(API.info);
162	    return r.status === 200 ? r.body.body : null;
163	  } catch {
164	    return null;
165	  }
166	}
167	
168	function stopLoops() {
169	  clearInterval(page.pollTimer);
170	  clearTimeout(page.retryTimer);
171	  page.pollTimer = null;
172	  if (page.socket) {
173	    page.socket.onclose = null;
174	    page.socket.close();
175	    page.socket = null;
176	  }
177	}
178	
179	async function unauthorized() {
180	  stopLoops();
181	  document.getElementById('bar').hidden = true;
182	  const verdict = infer401(page.stored, await readInfo());
183	  const again = 'Open the pairing window on the Mac and scan its code.';
184	  if (verdict === 'removed') {
185	    message('Removed', `This device was removed on the host. ${again}`);
186	  } else if (verdict === 'changed') {
187	    message('Identity changed', `The host's identity changed. ${again}`);
188	  } else if (verdict === 'unreachable') {
189	    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
190	  } else {
191	    message('Not paired', again);
192	  }
193	}
194	
195	// --- pairing and boot
196	
197	const PAIR_ERRORS = {
198	  pairing_closed: 'Pairing is not open on the Mac. Open the pairing window and scan again.',
199	  wrong_code: 'The code did not match. Scan the code again.',
200	  wrong_key: 'This is not the Mac whose code was scanned.',
201	  rate_limited: 'Too many tries. Wait a minute.',
202	};
203	
204	async function pairFrom(invite) {
205	  message('Pairing', 'Checking the host…');
206	  const info = await readInfo();
207	  if (!info) {
208	    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
209	    return;
210	  }
211	  if (info.spki_sha256 !== invite.key || info.server_id !== invite.id) {
212	    message(
213	      'Different Switchboard',
214	      'This address is a different Switchboard than the code was for. Nothing was sent.',
215	    );
216	    return;
217	  }
218	  const r = await call(API.pair, {
219	    method: 'POST',
220	    headers: { 'Content-Type': 'application/json' },
221	    body: JSON.stringify({
222	      code: invite.code,
223	      spki_sha256: invite.key,
224	      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints),
225	      transport: 'cookie',
226	    }),
227	  });
228	  if (r.status !== 200) {
229	    const code = r.body && r.body.error && r.body.error.code;
230	    message('Not paired', PAIR_ERRORS[code] || 'Pairing failed.');
231	    return;
232	  }
233	  page.stored = {
234	    server_id: info.server_id,
235	    spki_sha256: info.spki_sha256,
236	    server_name: info.server_name,
237	  };
238	  saveStored(page.stored);
239	  await start();
240	}
241	
242	async function boot() {
243	  page.stored = loadStored();
244	  const invite = parseFragment(location.hash);
245	  if (invite) {
246	    // Before anything else: the code is single use, but it should not
247	    // stay in the address bar.
248	    history.replaceState(null, '', location.pathname);
249	    await pairFrom(invite);
250	    return;
251	  }
252	  await start();
253	}
254	
255	async function start() {
256	  let r;
257	  try {
258	    r = await call(API.me);
259	  } catch {
260	    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
261	    return;
262	  }
263	  if (r.status === 401) {
264	    await unauthorized();
265	    return;
266	  }
267	  if (r.status !== 200) {
268	    message('Error', 'The host did not answer as expected.');
269	    return;
270	  }
271	  page.me = r.body.body;
272	  document.getElementById('host-name').textContent = page.me.server_name;
273	  document.getElementById('scope').textContent = `${page.me.scope} access`;
274	  document.getElementById('bar').hidden = false;
275	  await refresh();
276	  startPolling(POLL_FAST);
277	  connectSocket();
278	}
279	
280	// --- reading
281	
282	async function refresh() {
283	  if (page.refreshing) return;
284	  page.refreshing = true;
285	  try {
286	    const waiting = await call(API.waiting);
287	    if (waiting.status === 401) return await unauthorized();
288	    if (waiting.status !== 200) return;
289	    const marker = `${waiting.body.epoch}:${waiting.body.revision}`;
290	    if (!isCurrent(page.applied, waiting.body)) return;
291	    const projects = await call(API.projects);
292	    if (projects.status === 401) return await unauthorized();
293	    if (projects.status !== 200) return;
294	    const groups = [];
295	    for (const project of projects.body.body.projects) {
296	      const r = await call(route(API.sessions, project.id));
297	      if (r.status === 200) groups.push({ project, sessions: r.body.body.sessions });
298	    }
299	    page.groups = arrange(groups);
300	    page.marker = marker;
301	    page.applied = { epoch: waiting.body.epoch, revision: waiting.body.revision };
302	    if (page.open) await readSession();
303	    else drawList();
304	  } catch {
305	    // A dropped network: the next poll tries again.
306	  } finally {
307	    page.refreshing = false;
308	  }
309	}
310	
311	function drawList() {
312	  const nodes = [];
313	  const now = Date.now();
314	  for (const group of page.groups) {
315	    if (group.sessions.length === 0) continue;
316	    nodes.push(el('h2', group.project.name));
317	    for (const s of group.sessions) {
318	      const row = el('button', null, s.waiting ? 'row waiting' : 'row');
319	      if (s.waiting) {
320	        const reason = s.waiting_reason ? `: ${s.waiting_reason}` : '';
321	        row.append(el('span', `Waiting on you${reason}`, 'flag'));
322	      }
323	      row.append(el('strong', s.name));
324	      row.append(el('span', `${s.kind} · ${s.card} · ${ago(s.last_activity_ms, now)}`, 'meta'));
325	      row.addEventListener('click', () => openSession(s));
326	      nodes.push(row);
327	    }
328	  }
329	  if (nodes.length === 0) nodes.push(el('p', 'No sessions.', 'note'));
330	  show(...nodes);
331	}
332	
333	function findSession(id) {
334	  for (const group of page.groups) {
335	    const s = group.sessions.find((x) => x.id === id);
336	    if (s) return s;
337	  }
338	  return null;
339	}
340	
341	async function openSession(s) {
342	  page.open = s.id;
343	  await readSession();
344	}
345	
346	async function readSession() {
347	  const s = findSession(page.open);
348	  if (!s) {
349	    page.open = null;
350	    drawList();
351	    return;
352	  }
353	  const path = s.kind === 'claude' ? API.lastResponse : API.screen;
354	  const r = await call(route(path, s.id));
355	  if (r.status === 401) return unauthorized();
356	  if (r.status !== 200) return drawSession(s, 'Nothing to show.');
357	  // A content key has its own revision, so a reply is judged against
358	  // the last one read for that session, not the list's.
359	  if (!isCurrent(page.contentApplied[s.id], r.body)) return;
360	  page.contentApplied[s.id] = { epoch: r.body.epoch, revision: r.body.revision };
361	  drawSession(s, r.body.body.text);
362	}
363	
364	function drawSession(s, text) {
365	  const back = el('button', 'Back');
366	  back.addEventListener('click', () => {
367	    page.open = null;
368	    drawList();
369	  });
370	  const nodes = [back, el('h2', s.name), el('p', `${s.kind} · ${s.card}`, 'note')];
371	  if (s.waiting) nodes.push(el('p', `Waiting on you: ${s.waiting_reason || ''}`, 'error'));
372	  nodes.push(el('pre', text));
373	  if (page.me.scope === 'control') {
374	    nodes.push(...replyBox(s));
375	  }
376	  // Keep an unsent draft across a redraw.
377	  const draft = document.getElementById('reply');
378	  const typed = draft ? draft.value : '';
379	  show(...nodes);
380	  const box = document.getElementById('reply');
381	  if (box && typed) box.value = typed;
382	}
383	
384	function replyBox(s) {
385	  if (s.prompt_refusal) return [el('p', s.prompt_refusal, 'note')];
386	  const box = el('textarea');
387	  box.id = 'reply';
388	  box.setAttribute('aria-label', 'Reply');
389	  const status = el('p', '', 'note');
390	  const send = el('button', 'Send', 'primary');
391	  send.addEventListener('click', () => sendReply(s, box, status));
392	  return [box, send, status];
393	}
394	
395	async function sendReply(s, box, status) {
396	  const text = box.value.trim();
397	  if (!text) return;
398	  // The same text reuses its op, so a retry after a dropped reply is
399	  // answered from the host's log rather than typed twice.
400	  let pending = page.pending[s.id];
401	  if (!pending || pending.text !== text) {
402	    pending = { op: randomHex(12), text };
403	    page.pending[s.id] = pending;
404	  }
405	  status.textContent = 'Sending…';
406	  try {
407	    const r = await call(route(API.send, s.id), {
408	      method: 'POST',
409	      headers: { 'Content-Type': 'application/json' },
410	      body: JSON.stringify({ op: pending.op, text }),
411	    });
412	    if (r.status === 200) {
413	      delete page.pending[s.id];
414	      box.value = '';
415	      status.textContent = 'Sent. The session’s card shows progress.';
416	    } else if (r.status === 401) {
417	      await unauthorized();
418	    } else if (r.status === 403 && r.body.error.code === 'scope') {
419	      const me = await call(API.me);
420	      if (me.status === 200) page.me = me.body.body;
421	      status.textContent = 'This device can only read.';
422	      await readSession();
423	    } else {
424	      status.textContent = (r.body && r.body.error && r.body.error.message) || 'Not sent.';
425	    }
426	  } catch {
427	    status.textContent = 'No answer. Send again to retry.';
428	  }
429	}
430	
431	// --- staying current
432	
433	async function tick() {
434	  if (document.hidden) return;
435	  try {
436	    const r = await call(API.waiting);
437	    if (r.status === 401) return await unauthorized();
438	    if (r.status !== 200) return;
439	    if (`${r.body.epoch}:${r.body.revision}` !== page.marker) await refresh();
440	  } catch {
441	    // The host is not answering; keep trying.
442	  }
443	}
444	
445	function startPolling(ms) {
446	  page.pollMs = ms;
447	  clearInterval(page.pollTimer);
448	  page.pollTimer = setInterval(tick, ms);
449	}
450	
451	// The socket is an enhancement: a change arrives at once. Safari may
452	// never connect it over a certificate the user accepted, and polling
453	// carries on either way.
454	function connectSocket() {
455	  if (typeof WebSocket === 'undefined') return;
456	  const socket = new WebSocket(`wss://${location.host}${API.events}`);
457	  page.socket = socket;
458	  socket.onopen = () => {
459	    page.retryMs = RETRY_FIRST;
460	    startPolling(POLL_SLOW);
461	  };
462	  socket.onmessage = (event) => {
463	    let frame = null;
464	    try {
465	      frame = JSON.parse(event.data);
466	    } catch {
467	      return;
468	    }
469	    if (frame.type === 'changed' || frame.type === 'removed') refresh();
470	    if (frame.type === 'resync_required') lost();
471	  };
472	  socket.onerror = () => {};
473	  socket.onclose = () => lost();
474	}
475	
476	function lost() {
477	  if (page.socket) {
478	    page.socket.onclose = null;
479	    page.socket.close();
480	    page.socket = null;
481	  }
482	  startPolling(POLL_FAST);
483	  refresh();
484	  clearTimeout(page.retryTimer);
485	  page.retryTimer = setTimeout(connectSocket, page.retryMs);
486	  page.retryMs = Math.min(page.retryMs * 2, RETRY_MAX);
487	}
488	
489	if (typeof document !== 'undefined') {
490	  boot();
491	}
492	
493	if (typeof module !== 'undefined') {
494	  module.exports = { API, parseFragment, deviceName, infer401, isCurrent, route, arrange, ago };
495	}
496

